<script setup lang="ts">
import {h,onMounted,ref} from 'vue'
import {NAlert,NButton,NDataTable,NInput,NModal,NPagination,NTag,useMessage} from 'naive-ui'
import {api} from '../api'
import {energy,energyAmount,requestKey} from '../energy'
defineProps<{me:any}>();const emit=defineEmits<{changed:[]}>(),message=useMessage()
const amount=ref(''),key=ref(''),confirm=ref(false),busy=ref(false),working=ref(false),error=ref(''),page=ref(1),pages=ref(1),rows=ref<any[]>([])
const labels:Record<string,string>={pending:'待确认',approved:'已到账',rejected:'已拒绝',cancelled:'已取消'}
const columns=[{title:'申请时间',key:'created_at',minWidth:165,render:(r:any)=>new Date(r.created_at*1000).toLocaleString('zh-CN')},{title:'补充数量',key:'amount_cents',minWidth:130,render:(r:any)=>energy(r.amount_cents)},{title:'状态',key:'status',minWidth:95,render:(r:any)=>h(NTag,{bordered:false,type:r.status==='approved'?'success':r.status==='pending'?'warning':'default'},()=>labels[r.status]||r.status)},{title:'备注',key:'note',minWidth:150},{title:'操作',key:'action',width:80,render:(r:any)=>r.status==='pending'?h(NButton,{size:'small',disabled:working.value,onClick:()=>cancel(r.id)},()=> '取消'):'—'}]
async function load(value=page.value){busy.value=true;error.value='';try{const data=await api('/api/me/energy?page='+value);rows.value=data.data;page.value=data.current_page;pages.value=data.last_page}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function prepare(){try{energyAmount(amount.value);error.value='';confirm.value=true}catch(e){error.value=(e as Error).message}}
async function submit(){if(working.value)return;working.value=true;error.value='';try{const value=energyAmount(amount.value);if(!key.value)key.value=requestKey();await api('/api/me/energy',{method:'POST',body:JSON.stringify({amount:value,request_id:key.value})});key.value='';amount.value='';confirm.value=false;message.success('已提交补充申请，等待管理员确认');await load(1)}catch(e){error.value=(e as Error).message}finally{working.value=false}}
async function cancel(id:string){if(working.value)return;working.value=true;try{await api('/api/me/energy/'+encodeURIComponent(id)+'/cancel',{method:'POST',body:'{}'});await load();emit('changed')}catch(e){error.value=(e as Error).message}finally{working.value=false}}
onMounted(()=>load())
</script>
<template><div class="page-heading"><div><span class="eyebrow">ENERGY</span><h1>补充能量</h1></div><n-button :loading="busy" @click="load()">刷新</n-button></div><n-alert v-if="error" type="error" class="space-bottom">{{error}}</n-alert><article class="surface"><span class="muted">可用能量</span><h2>{{energy(me.balance_cents)}}</h2><div class="button-row"><n-input :value="amount" :disabled="working" placeholder="自定义补充数量" :input-props="{inputmode:'decimal',maxlength:20}" style="max-width:280px" @update:value="v=>{amount=v;key=''}"/><n-button type="primary" :disabled="!amount" @click="prepare">申请补充</n-button></div><p class="small muted">管理员确认后到账</p></article><article class="surface" style="margin-top:20px"><h2>补充记录</h2><n-data-table :columns="columns" :data="rows" :loading="busy" :bordered="false" :scroll-x="650"/><n-pagination v-model:page="page" :page-count="pages" style="margin-top:16px;justify-content:flex-end" @update:page="load"/></article><n-modal v-model:show="confirm" preset="card" title="确认补充能量" :closable="!working" :mask-closable="!working" :close-on-esc="!working" style="width:420px;max-width:calc(100vw - 32px)"><p>申请补充 <strong>{{amount}} 能量</strong></p><p class="muted">提交后等待管理员确认，确认前不会计入可用能量。</p><n-alert v-if="error" type="error">{{error}}</n-alert><template #footer><div class="button-row" style="justify-content:flex-end"><n-button :disabled="working" @click="confirm=false">取消</n-button><n-button type="primary" :loading="working" @click="submit">确认提交</n-button></div></template></n-modal></template>
